        ))}\n                </Bar>\n              </BarChart>\n            </ResponsiveContainer>\n          </AnalyticsChartShell>\n        </CardContent>\n      </Card>\n\n      {/* From here on: conclusions first, then when, how much, and how the gaze moved. */}\n      <AoiFindingsCard findings={findings} />\n\n      <AoiSequenceCard\n        discovery={discovery}\n        sequence={sequence}\n        visits={visits}\n        loading={fixationsLoading}\n        error={fixationsError}\n        onsetS={onsetS}\n        endS={endS}\n        events={events}\n      />\n\n      <AoiMetricsCard\n        aois={data.aois}\n        ranks={ranks}\n        onsetS={onsetS}\n        visits={visits}\n        outside={outside}\n        totalFixations={data.total_fixations}\n      />\n\n      <div className={cn(\"grid gap-4\", sideBySideClass(fixatedAoiCount))}>\n        <AoiTransitionsCard aois={data.aois} summary={transitions} />\n        <AoiSignalPeaksCard events={events} onsetS={onsetS} />\n      </div>\n    </div>\n  )\n}\n","usedDeprecatedRules":[]},{"filePath":"C:\\AAMisArchivos\\AAprogramming\\AAAWebDeb\\Bioseñales\\NeuroDatics-App\\frontend\\features\\analytics\\components\\AoiOverlay.tsx","messages":[],"suppressedMessages":[],"errorCount":0,"fatalErrorCount":0,"warningCount":0,"fixableErrorCount":0,"fixableWarningCount":0,"usedDeprecatedRules":[]},{"filePath":"C:\\AAMisArchivos\\AAprogramming\\AAAWebDeb\\Bioseñales\\NeuroDatics-App\\frontend\\features\\analytics\\components\\ChartDragZoom.tsx","messages":[],"suppressedMessages":[],"errorCount":0,"fatalErrorCount":0,"warningCount":0,"fixableErrorCount":0,"fixableWarningCount":0,"usedDeprecatedRules":[]},{"filePath":"C:\\AAMisArchivos\\AAprogramming\\AAAWebDeb\\Bioseñales\\NeuroDatics-App\\frontend\\features\\analytics\\components\\DeviceDistanceTab.tsx","messages":[],"suppressedMessages":[{"ruleId":"@typescript-eslint/no-explicit-any","severity":2,"message":"Unexpected any. Specify a different type.","line":226,"column