       alt=\"Escenario\"\n                        className=\"analytics-visual-image\"\n                        onLoad={computeLetterbox}\n                      />\n                    )}\n\n                    {/* Heatmap PNG overlay, pinned to the measured stimulus box */}\n                    {overlayUrl && scenarioImageUrl && letterbox && (\n                      <img\n                        src={overlayUrl}\n                        alt=\"Mapa de calor\"\n                        aria-hidden=\"true\"\n                        className=\"pointer-events-none z-10\"\n                        style={{\n                          ...containedImageBoxStyle(letterbox),\n                          opacity: 0.82,\n                        }}\n                      />\n                    )}\n\n                    {/* Optional purple tint overlay */}\n                    {showPurple && (\n                      <div\n                        className=\"pointer-events-none absolute inset-0\"\n                        style={{\n                          background: \"rgba(60, 0, 160, 0.52)\",\n                          mixBlendMode: \"multiply\",\n                        }}\n                      />\n                    )}\n\n                    {showAois && <AoiOverlay aois={aois} box={letterbox} />}\n                  </div>\n\n                  {/* Controls bar */}\n                  <div className=\"mt-4 flex flex-wrap items-center justify-between gap-4 rounded-xl border border-border bg-muted/30 px-5 py-3\">\n                    <AoiLegend aois={showAois ? aois : []} />\n                    <div className=\"ml-auto flex items-center gap-3\">\n                      <AoiToggleButton\n                        enabled={showAois}\n                        onToggle={() => setShowAois((value) => !value)}\n                        disabled={aois.length === 0 || aoiLoading}\n                        count={aois.length}\n                      />\n                      <Button aria-pressed={showPurple} size=\"sm\" variant=\"selection\"\n                        type=\"button\"\n                        onClick={() => setShowPurple((p) => !p)}\n                        className=\"\"\n                      >\n                        Filtro violeta\n                      </Button>\n                    </div>\n                  </div>\n                </>\n              )}\n            </>\n          )}\n        </CardContent>\n      </Card>\n\n    </div>\n  )\n}\n","usedDeprecatedRules":[]},{"filePath":"C:\\AAMisArchivos\\AAprogramming\\AAAWebDeb\\Bioseñales\\NeuroDatics-App\\frontend\\features\\analytics\\components\\InfoChip.tsx","messages":[],"suppressedMessages":[],"errorCount":0,"fatalErrorCount":0,"warningCount":0,"fixableErrorCount":0,"fixableWarningCount":0,"usedDeprecatedRules":[]},{"filePath":"C:\\AAMisArchivos\\AAprogramming\\AAAWebDeb\\Bioseñales\\NeuroDatics-App\\frontend\\features\\analytics\\components\\KpiCard.tsx","messages":[],"suppressedMessages":[],"errorCount":0,"fatalErrorCount":0,"warningCount":0,"fixableErrorCount":0,"fixableWarningCount":0,"usedDeprecatedRules":[]},{"filePath":"C:\\AAMisArchivos\\AAprogramming\\AAAWebDeb\\Bioseñales\\NeuroDatics-App\\frontend\\features\\analytics\\components\\MissingStimulusImage.tsx","messages":[],"suppressedMessages":[],"errorCount":0,"fatalErrorCount":0,"warningCount":0,"fixableErrorCount":0,"fixableWarningCount":0,"usedDeprecatedRules":[]},{"filePath":"C:\\AAMisArchivos\\AAprogramming\\AAAWebDeb\\Bioseñales\\NeuroDatics-App\\frontend\\features\\analytics\\components\\PlaceholderTab.tsx","messages":[],"suppressedMessages":[],"errorCount":0,"fatalErrorCount":0,"warningCount":0,"fixableErrorCount":0,"fixableWarningCount":0,"usedDeprecatedRules":[]},{"filePath":"C:\\AAMisArchivos\\AAprogramming\\AAAWebDeb\\Bioseñales\\NeuroDatics-App\\frontend\\features\\analytics\\components\\PupilDilationTab.tsx","messages":[],"suppressedMessages":[{"ruleId":"@typescript-eslint/no-explicit-any","severity":2,"mes